CREATE VIEW tickets.view_clientes_con_tickets AS
 WITH clientes_unificados AS (
         SELECT cn.id AS pk_cliente,
            cn.str_cedula AS documento,
            ((cn.str_nombre || ' '::text) || cn.str_apellido) AS nombre_o_razon_social,
            cn.str_email AS email,
            cn.str_telefono AS telefono,
            'Natural'::text AS tipo_cliente,
            cn.created_at AS cliente_created_at,
            t.id AS ticket_id,
            t.str_ticket,
            t.tipo_ticket_id,
            t.creador_agente_id,
            t.departamento_id,
            t.categoria_id,
            t.prioridad_id,
            t.canal_id,
            t.estatus_id,
            t.usuario_asignado_id,
            t.str_asunto,
            t.str_descripcion,
            t.int_sla,
            t.str_ruta_imagen,
            t.str_ruta_video,
            t.str_ruta_audio,
            t.created_at AS ticket_created_at,
            t.dmt_fecha_vencimiento_sla,
            t.dmt_fecha_cierre
           FROM (tickets.tbl_clientes_naturales cn
             JOIN tickets.tbl_tickets t ON ((cn.id = t.cliente_id)))
        UNION ALL
         SELECT cj.id AS pk_cliente,
            cj.str_rif AS documento,
            cj.str_razon_social AS nombre_o_razon_social,
            cj.str_email AS email,
            cj.str_telefono AS telefono,
            'Jurídico'::text AS tipo_cliente,
            cj.created_at AS cliente_created_at,
            t.id AS ticket_id,
            t.str_ticket,
            t.tipo_ticket_id,
            t.creador_agente_id,
            t.departamento_id,
            t.categoria_id,
            t.prioridad_id,
            t.canal_id,
            t.estatus_id,
            t.usuario_asignado_id,
            t.str_asunto,
            t.str_descripcion,
            t.int_sla,
            t.str_ruta_imagen,
            t.str_ruta_video,
            t.str_ruta_audio,
            t.created_at AS ticket_created_at,
            t.dmt_fecha_vencimiento_sla,
            t.dmt_fecha_cierre
           FROM (tickets.tbl_clientes_juridicos cj
             JOIN tickets.tbl_tickets t ON ((cj.id = t.cliente_juridico_id)))
        )
 SELECT c.pk_cliente AS id,
    c.documento AS cedula,
    c.nombre_o_razon_social AS cliente,
    c.telefono,
    c.email AS correo,
    c.tipo_cliente,
    c.cliente_created_at AS created_at,
    count(c.ticket_id) AS tickets,
    max(c.ticket_created_at) AS ultima_atencion,
    COALESCE(json_agg(json_build_object('id', c.ticket_id, 'str_ticket', c.str_ticket, 'tipo_ticket_id', c.tipo_ticket_id, 'creador_agente_id', c.creador_agente_id, 'departamento_id', c.departamento_id, 'categoria_id', c.categoria_id, 'prioridad_id', c.prioridad_id, 'canal_id', c.canal_id, 'estatus_id', c.estatus_id, 'usuario_asignado_id', c.usuario_asignado_id, 'str_asunto', c.str_asunto, 'str_descripcion', c.str_descripcion, 'int_sla', c.int_sla, 'str_ruta_imagen', c.str_ruta_imagen, 'str_ruta_video', c.str_ruta_video, 'str_ruta_audio', c.str_ruta_audio, 'created_at', c.ticket_created_at, 'dmt_fecha_vencimiento_sla', c.dmt_fecha_vencimiento_sla, 'dmt_fecha_cierre', c.dmt_fecha_cierre, 'categoria_nombre', cat.str_nombre, 'prioridad_nombre', p.str_nombre, 'estatus_nombre', est.str_nombre, 'canal_nombre', can.str_nombre, 'tipo_ticket', tt.str_nombre, 'asignado_nombre', u.str_nombre, 'asignado_apellido', u.str_apellido, 'creador_nombre', creador.str_nombre, 'creador_apellido', creador.str_apellido, 'creador_correo', creador.str_email) ORDER BY c.ticket_created_at DESC) FILTER (WHERE (c.ticket_id IS NOT NULL)), '[]'::json) AS lista_tickets
   FROM (((((((clientes_unificados c
     LEFT JOIN public.cat_datos_maestros cat ON ((c.categoria_id = cat.id)))
     LEFT JOIN public.cat_datos_maestros p ON ((c.prioridad_id = p.id)))
     LEFT JOIN public.cat_datos_maestros est ON ((c.estatus_id = est.id)))
     LEFT JOIN public.cat_datos_maestros can ON ((c.canal_id = can.id)))
     LEFT JOIN public.cat_datos_maestros tt ON ((c.tipo_ticket_id = tt.id)))
     LEFT JOIN public.tbl_usuarios u ON ((c.usuario_asignado_id = u.id)))
     LEFT JOIN public.tbl_usuarios creador ON ((c.creador_agente_id = creador.id)))
  GROUP BY c.pk_cliente, c.documento, c.nombre_o_razon_social, c.telefono, c.email, c.tipo_cliente, c.cliente_created_at;


